#include "code_rule.hpp"

class CppStyleRule : public CodeRule {
public:
    std::string name() const override {
        return "C++17 Core Guidelines Style Rule";
    }

    void modifyHeader(const UmlClass& /*umlClass*/, std::string& headerCode) override {
        std::string banner = "// ====================================================\n"
                             "// Auto-generated by UML Tool (ALT Linux C++17 Standard)\n"
                             "// ====================================================\n\n";
        headerCode = banner + headerCode;
    }

    void modifySource(const UmlClass& /*umlClass*/, std::string& sourceCode) override {
        std::string banner = "// ====================================================\n"
                             "// Implementation module auto-generated by UML Tool\n"
                             "// ====================================================\n\n";
        sourceCode = banner + sourceCode;
    }
};

extern "C" CodeRule* create_rule() {
    return new CppStyleRule();
}
